-- TEST DATA ONLY: deterministic Notifications integration scenarios using existing active staff.
insert into public.notification_queue (tenant_id,recipient_type,recipient_id,channel,message_body,priority,status,scheduled_at,metadata)
select cu.tenant_id,'staff',cu.id,'in_app',case when cu.role='clinic_admin' then 'Demo notification: clinic operations summary is ready.' when cu.role='doctor' then 'Demo notification: clinical follow-up requires review.' when cu.role='receptionist' then 'Demo notification: reception queue has a pending action.' else 'Demo notification: team update is available.' end,5,'queued',now()-interval '5 minutes',jsonb_build_object('title',case when cu.role='clinic_admin' then 'Operations summary' when cu.role='doctor' then 'Clinical follow-up' when cu.role='receptionist' then 'Reception action' else 'Team update' end,'type','demo_test_notification','test_data',true,'source','CORE SYSTEM Notifications integration test')
from public.clinic_users cu where cu.is_active=true and cu.deleted_at is null and cu.auth_user_id is not null and not exists(select 1 from public.notification_queue nq where nq.tenant_id=cu.tenant_id and nq.recipient_type='staff' and nq.recipient_id=cu.id and nq.channel='in_app' and nq.metadata->>'source'='CORE SYSTEM Notifications integration test');
with recipients as (select cu.tenant_id,cu.id,row_number() over(partition by cu.tenant_id order by case when cu.role='doctor' then 1 else 2 end,cu.full_name) rn from public.clinic_users cu where cu.is_active=true and cu.deleted_at is null and cu.auth_user_id is not null)
insert into public.notification_queue (tenant_id,recipient_type,recipient_id,channel,message_body,priority,status,scheduled_at,metadata)
select r.tenant_id,'staff',r.id,'in_app','Demo shared notification: verify independent read state per user.',5,'queued',now()-interval '2 minutes',jsonb_build_object('title','Personal read-state test','type','demo_shared_notification','test_data',true,'source','CORE SYSTEM Notifications integration test','scenario','two-user-read-isolation') from recipients r where r.rn<=2 and not exists(select 1 from public.notification_queue nq where nq.tenant_id=r.tenant_id and nq.recipient_type='staff' and nq.recipient_id=r.id and nq.metadata->>'scenario'='two-user-read-isolation');
